def resolve_root_profiles(case, need_defaults=True):
    '''(names, FP64 table [S, L], source). Custom case rows override defaults; grass/shrub rows are required
    only when plants are assigned by the default grass/shrub class (no explicit root_profile_id).'''
    L, mb = case['layers'], case['max_bytes']
    custom = case.get('root_layer_fractions')
    if custom is None:
        named, source = validate_root_layer_fractions(default_root_layer_fractions(L, mb), L), 'default'
    else:
        named, source = validate_root_layer_fractions(custom, L), 'case'
    if need_defaults:
        for k in ('grass', 'shrub'):
            if k not in named:
                raise ValueError(f'root_layer_fractions must name the default class {k!r} '
                                 '(plants are assigned by class unless root_profile_id is supplied)')
    names = list(named)
    if 8 * len(names) * L > mb:
        raise _reject('daily_water_growth.init', 'root profile table exceeds max_bytes',
                      {'profile_table_bytes': 8 * len(names) * L, 'max_bytes': int(mb)})
    table = np.ascontiguousarray([named[n] for n in names], dtype=np.float64).reshape(len(names), L)
    return names, table, source


def _validate_profile_ids(v, P, S):
    '''Explicit profile IDs: integer (not bool/float), 1-D, length P, 0 <= id < S; checked BEFORE any
    conversion to int32 or large allocation/transfer.'''
    if isinstance(v, np.ndarray):
        if v.dtype.kind not in 'iu':
            raise ValueError(f'root_profile_id must have an integer dtype (not bool/float), got {v.dtype}')
    else:
        if isinstance(v, (str, bytes, dict)) or not hasattr(v, '__len__'):
            raise ValueError('root_profile_id must be a 1-D integer sequence or array')
        if len(v) != P:
            raise ValueError(f'root_profile_id has {len(v)} entries, expected population {P}')
        for e in v:
            if isinstance(e, (bool, np.bool_)) or not isinstance(e, (int, np.integer)):
                raise ValueError(f'root_profile_id entries must be integers (not bool/float), got {e!r}')
        v = np.asarray(v, dtype=np.int64)
    if v.ndim != 1 or int(v.shape[0]) != P:
        raise ValueError(f'root_profile_id must have shape ({P},), got {tuple(v.shape)}')
    if int(v.min()) < 0 or int(v.max()) >= S:
        raise ValueError(f'root_profile_id values must lie in [0, {S}) (named profile table), '
                         f'got range [{int(v.min())}, {int(v.max())}]')
    return np.ascontiguousarray(v, dtype=np.int32)

